public class Bank {
    static class InsufficientFundsException extends Exception {
        InsufficientFundsException(String msg) { super(msg); }   // custom checked
    }
    private double balance = 100;

    void withdraw(double amt) throws InsufficientFundsException {  // declares
        if (amt <= 0) throw new IllegalArgumentException("Amount must be positive"); // triggers
        if (amt > balance) throw new InsufficientFundsException("Balance too low");
        balance -= amt;
    }
    public static void main(String[] args) {
        Bank b = new Bank();
        try {
            b.withdraw(500);
            System.out.println("done");           // skipped when exception occurs
        } catch (InsufficientFundsException e) {  // specific first
            System.out.println("Declined: " + e.getMessage());
        } catch (Exception e) {                   // general last
            System.out.println("Other: " + e.getMessage());
        } finally {
            System.out.println("Always runs");
        }
        try {
            int x = Integer.parseInt("abc");
        } catch (NumberFormatException e) {
            System.out.println("Not a number");
        }
    }
}

